 {let item=p.item_mut(audio).unwrap();item.metadata.insert("Description".into(),"Source description".into());item.metadata.insert("Tape Name".into(),"Original tape".into());let m=item.as_media_mut().unwrap();m.mark_in=Some(Tick(10));m.mark_out=Some(Tick(99));m.markers.push(marker);m.proxy=Some(MediaRef::File{path:"/not-opened/proxy.wav".into()});m.offline=true;m.interpret.frame_rate=Some(FrameRate::FPS_29_97);m.info.start_timecode=Some(1000);}
